// components/pages/Report.js
import React, { useState, useEffect } from 'react';
import { apiCall, escapeHtml } from '../../utils/api';

const Report = ({ currentUserRole }) => {
  const [reportType, setReportType] = useState('Line');
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);

  const loadData = async () => {
    setLoading(true);
    if (reportType === 'Line') {
      const result = await apiCall('getLines');
      if (result.success) {
        setData(result.lines || []);
      }
    } else {
      const [tillsResult, linesResult] = await Promise.all([
        apiCall('getTills'),
        apiCall('getLines')
      ]);
      
      if (tillsResult.success) {
        const lines = linesResult.lines || [];
        const lineMap = new Map();
        lines.forEach(line => {
          const normalizedPhone = normalizePhone(line.phone);
          lineMap.set(normalizedPhone, line);
        });
        
        const formattedData = (tillsResult.tills || []).map(t => {
          const ownerLine = lineMap.get(normalizePhone(t.phone || ''));
          return {
            ...t,
            ownerPhone: ownerLine ? ownerLine.phone : (t.phone || '-')
          };
        });
        setData(formattedData);
      }
    }
    setLoading(false);
  };

  useEffect(() => {
    loadData();
  }, [reportType]);

  const normalizePhone = (phone) => {
    if (!phone) return '';
    let normalized = String(phone).replace(/\D/g, '');
    if (normalized.startsWith('254')) {
      normalized = normalized.substring(3);
    } else if (normalized.startsWith('0')) {
      normalized = normalized.substring(1);
    }
    return normalized;
  };

  if (loading) {
    return (
      <div className="loading">
        <i className="fas fa-spinner fa-pulse"></i> Loading report...
      </div>
    );
  }

  const renderTable = () => {
    if (data.length === 0) {
      return (
        <div className="empty-state">
          <i className="fas fa-inbox"></i>
          <br />No {reportType === 'Line' ? 'lines' : 'tills'} registered yet
        </div>
      );
    }

    if (reportType === 'Line') {
      return (
        <div className="table-wrapper">
          <table className="modern-table">
            <thead>
              <tr>
                <th>Name</th>
                <th>ID Number</th>
                <th>Phone</th>
                <th>DOB</th>
                <th>Date Created</th>
              </tr>
            </thead>
            <tbody>
              {data.map((line, index) => (
                <tr key={index}>
                  <td><strong>{escapeHtml(line.name || '-')}</strong></td>
                  <td>{escapeHtml(line.idNumber || '-')}</td>
                  <td>{escapeHtml(line.phone || '-')}</td>
                  <td>{escapeHtml(line.dob || '-')}</td>
                  <td>{line.dateCreated ? new Date(line.dateCreated).toLocaleDateString() : '-'}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      );
    } else {
      return (
        <div className="table-wrapper">
          <table className="modern-table">
            <thead>
              <tr>
                <th>Name</th>
                <th>Owner Phone</th>
                <th>Till Number</th>
                <th>Store</th>
                <th>Units</th>
                <th>Status</th>
                <th>Date Created</th>
              </tr>
            </thead>
            <tbody>
              {data.map((till, index) => (
                <tr key={index}>
                  <td><strong>{escapeHtml(till.name || '-')}</strong></td>
                  <td>{escapeHtml(till.ownerPhone)}</td>
                  <td>{escapeHtml(till.tillNumber || '-')}</td>
                  <td>{escapeHtml(till.storeNumber || '-')}</td>
                  <td><span className="units-black">{till.units || 0} units</span></td>
                  <td>
                    <span className={`badge ${till.status === 'active' ? 'badge-success' : 'badge-danger'}`}>
                      {till.status === 'active' ? 'Active' : 'Inactive'}
                    </span>
                  </td>
                  <td>{till.dateCreated ? new Date(till.dateCreated).toLocaleDateString() : '-'}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      );
    }
  };

  return (
    <>
      <h3 className="section-title"><i className="fas fa-chart-line"></i> Analytics Reports</h3>
      <div className="submenu">
        <button 
          className={reportType === 'Line' ? 'active' : ''}
          onClick={() => setReportType('Line')}
        >
          <i className="fas fa-users"></i> Line Report
        </button>
        <button 
          className={reportType === 'Till' ? 'active' : ''}
          onClick={() => setReportType('Till')}
        >
          <i className="fas fa-cash-register"></i> Till Report
        </button>
      </div>
      {renderTable()}
    </>
  );
};

export default Report;
